public interface IFeatureFlagService
{
    bool IsEnabled(string featureName);
}

public class ConfigurationFeatureFlagService : IFeatureFlagService
{
    private readonly IConfiguration _configuration;

    public ConfigurationFeatureFlagService(IConfiguration configuration)
    {
        _configuration = configuration;
    }

    public bool IsEnabled(string featureName)
    {
        return _configuration.GetValue<bool>($"Features:{featureName}");
    }
}

// Usage in a controller
[ApiController]
[Route("api/[controller]")]
public class CheckoutController : ControllerBase
{
    private readonly IFeatureFlagService _flags;

    public CheckoutController(IFeatureFlagService flags)
    {
        _flags = flags;
    }

    [HttpPost]
    public IActionResult Complete(Order order)
    {
        if (_flags.IsEnabled("ExpressCheckoutV2"))
        {
            return CompleteWithExpressV2(order);
        }
        return CompleteWithLegacy(order);
    }
}
